#!/usr/bin/env bash
# Re-renders the raster listing assets into .wordpress-org/ from their SVG sources.
#
# The SVGs are generated by the Mammoth WP brand kit (mammothwp/brand, `make`),
# which is the source of truth for the split-panel layout, colours and fonts;
# copy its plugins/<slug>/listing/ output into .wordpress-org/ (icon.svg) and
# docs/brand-assets/src/ (banner sources; .wordpress-org/ holds only files
# wordpress.org uses, as it is synced 1:1 to SVN /assets). This script only rasterises: icon.svg -> icon-*.png and,
# when present, src/banner-<WxH>.svg -> banner-<WxH>.png. Needs rsvg-convert.
#
# Usage: bin/build-assets.sh

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DIR="${ROOT}/.wordpress-org"
BRAND_DIR="${ROOT}/docs/brand-assets"
# shellcheck source=/dev/null
source "${BRAND_DIR}/assets.conf"

command -v rsvg-convert >/dev/null || { echo "rsvg-convert is required" >&2; exit 1; }

for size in ${ICON_SIZES}; do
	rsvg-convert -w "${size}" -h "${size}" "${DIR}/icon.svg" -o "${DIR}/icon-${size}x${size}.png"
done

for size in ${BANNER_SIZES}; do
	src="${BRAND_DIR}/src/banner-${size}.svg"
	[ -f "${src}" ] || continue
	rsvg-convert -w "${size%x*}" -h "${size#*x}" "${src}" -o "${DIR}/banner-${size}.png"
done

echo "Rendered assets for ${PLUGIN_NAME} in ${DIR}"
